module benchmark/solution

import std/fs (readFile, fileExists)
import std/json (Json, decode, getString, getInt, getArray, allStrings)
import std/list (length, filter)
import std/string (chars)
import std/option (Some, None)
import std/result (Result, Ok, Err)

type Config = {app_name: string, version: string, port: int, features: [string]}

pure func validateConfig(obj: Json) -> Result[Config, string] {
  match (getString(obj, "app_name"), getString(obj, "version"), getInt(obj, "port"), getArray(obj, "features")) {
    (Some(name), Some(version), Some(port), Some(items)) =>
      match allStrings(items) {
        None => Err("Features must be strings"),
        Some(features) => {
          let dots = length(filter(\c. c == ".", chars(version)));
          if port < 1024 || port > 65535 then Err("Port must be between 1024 and 65535")
          else if dots != 2 then Err("Version must contain exactly two dots")
          else if length(features) == 0 then Err("Features must not be empty")
          else Ok({app_name: name, version: version, port: port, features: features})
        }
      },
    _ => Err("Missing or invalid config fields")
  }
}

func loadConfig(path: string) -> Result[Config, string] ! {FS} {
  if not fileExists(path) then Err("Config file not found")
  else {
    let content = readFile(path);
    match decode(content) {
      Err(message) => Err(message),
      Ok(obj) => validateConfig(obj)
    }
  }
}

export func main() -> () ! {IO, FS} {
  match loadConfig("app_config.json") {
    Ok(config) => println("Loaded ${config.app_name} v${config.version} on port ${config.port} with ${length(config.features)} features"),
    Err(message) => println(message)
  }
}

